for st in s:
 for x,y,z in st['points']:
  v=round((.0135925-x)*1000/PIX_MM-.5);u=round((.1135925-y)*1000/PIX_MM-.5)
  r=(1.3+(0.016-z)*400) if z>=.016 else (2.8+(.012-z)*375 if z>=.012 else 5.8+(.008-z)*750)
  rp=max(2,int(round(r/PIX_MM)));a=max(0,v-rp);b=min(1024,v+rp+1);c=max(0,u-rp);d=min(1024,u+rp+1);yy,xx=np.ogrid[a:b,c:d];pred[a:b,c:d]|=(yy-v)**2+(xx-u)**2<=rp**2
