print('area pred actual',pred.sum(),actual.sum());print('IoU',np.logical_and(actual,pred).sum()/np.logical_or(actual,pred).sum());
for name,a in [('pred',pred),('actual',actual)]:
 y,x=np.where(a);print(name,'bbox',(y.min(),y.max(),x.min(),x.max()),'center',(y.mean(),x.mean()))
for dy in [-12,-8,-4,0,4,8,12]:
 for dx in [-12,-8,-4,0,4,8,12]:
